import { StrictMode, useEffect, useMemo, useRef, useState } from "react";
import type { ReactNode } from "react";
import { createRoot } from "react-dom/client";
import "./styles.css";

type Status = "CURRENT" | "STALE" | "UNKNOWN" | "UNAVAILABLE" | "CONFLICTING";
type Settings = {
  version: number; appearance: "system" | "light" | "night"; accent: "ember" | "sage" | "sky";
  density: "comfortable" | "compact"; reduced_motion: boolean; text_scale: "small" | "normal" | "large";
  display_mode: "wall" | "tablet" | "phone" | "desktop"; visible_widgets: string[]; widget_order: string[];
};
type Bootstrap = { identity: { display_name: string; assurance: string }; household: { name: string }; theme: Pick<Settings, "appearance" | "accent" | "density" | "reduced_motion" | "text_scale">; layout: Pick<Settings, "display_mode" | "visible_widgets" | "widget_order">; csrf_token: string };
type Task = { task_id: string; title: string; status: string; next_run_at?: string };
type CalendarEvent = { event_id: string; title: string; start_at: string; end_at: string; status: string; version?: number };
type Device = { device_id: string; name: string; kind: string; state: string };
type Room = { place_id: string; name: string; kind: string; devices: Device[] };
type Space = { place_id: string; name: string; kind: string; parent_id?: string | null };
type DeviceCapability = { type: string; label: string; readable: boolean; writable: boolean; state: string; truth_status: string; observed_at?: string | null };
type ProviderDevice = { external_object_kind: string; device_handle: string; present: boolean; state?: string; truth_status?: string; observed_at?: string | null; capabilities?: DeviceCapability[]; metadata: Record<string, string | null> };
type AlertPolicy = { policy_id: string; resource_ids: string[]; event_type: string; timezone: string; start_local: string; end_local: string; priority: number; guaranteed_attention: boolean; delivery_mode: "SENTRY_COGNITION" | "NOTIFICATION"; enabled: boolean; version: number };
type AlertEvent = { alert_id: string; source_event_id?: string | null; resource_id: string; resource_name: string; event_type: string; occurred_at: string; priority: number; delivery_mode: string; delivery_status: string };
type Page<T> = { items: T[]; next_cursor: string | null };
type NotificationRoute = { route_id: string; label: string; enabled: boolean; minimum_priority: number; version: number; provider: string; destination: string };
type BackupRecord = { backup_id: string; captured_at: string; size_bytes: number; sha256: string; schema_version: string; restorable: boolean };
type SceneStep = { resource_id: string; desired_on: boolean };
type Scene = { scene_id: string; name: string; steps: SceneStep[]; enabled: boolean; version: number; updated_at: string };
type Automation = { automation_id: string; name: string; trigger_resource_id: string; trigger_state: "on" | "off"; action_resource_id: string; action_desired_on: boolean; enabled: boolean; version: number; updated_at: string };
type Home = { household: { name: string; status: Status; summary: string }; security: { status: Status; label: string }; presence: { people: { name: string; state: string }[] }; weather: { status: Status; summary: string }; calendar: CalendarEvent[]; tasks: Task[]; controls: { control_id: string; label: string; state: string; capability?: string }[]; activity: { summary: string; status: Status }[]; voice: { status: Status; label: string }; rooms: Room[]; notifications: { notification_id: string; summary: string; status: Status; importance?: string; occurred_at?: string }[]; reports: { report_id: string; summary: string; status: string; disposition?: string; completed_at?: string | null }[]; recent_actions: { action_id: string; tool_id: string; status: string; detail: string; updated_at: string }[]; pending_approvals: { approval_id: string; action_id: string; tool_id: string; status: string; summary: string; expires_at: string; continuation: string }[]; health: { status: Status | string; summary: string; unavailable: string[]; degraded: string[] } };
type Capability = { id: string; label: string; state: string; detail?: string };
type IntegrationHealth = { health?: string; connected_version?: string | null; last_successful_state_sync?: string | null; last_received_event?: string | null; subscriptions_active?: boolean; discovered_counts?: Record<string, number>; mapped_count?: number; unmapped_count?: number; reconnect_attempt?: number; last_error_category?: string | null };
type Integration = { plugin_id: string; name: string; description: string; state: string; enabled: boolean; capabilities: string[]; manageable: boolean; error?: string | null; health?: IntegrationHealth };
type ZHASetupField = { name: "device_path" | "radio_type" | "baudrate" | "flow_control"; required: boolean; type: "string" | "integer"; options?: string[] };
type ZHASetup = { setup_id: string; step_id: string; fields: ZHASetupField[] };
type MutationOutcome = { status: string; operation: string; reason?: string; detail?: string; result?: unknown; evidence?: unknown };
type ConversationResult = { request_id: string; status: string; lifecycle: string; response?: string | null; detail?: string | null; available: boolean };
type Preference = { preference_id: string; content: string; category: "alerts" | "comfort" | "meals" | "shopping" | "privacy" | "other"; created_at: string; status: string; provenance?: { kind?: string } };

const api = async <T,>(path: string, options?: RequestInit): Promise<T> => {
  const response = await fetch(path, { ...options, credentials: "same-origin", headers: { Accept: "application/json", ...(options?.headers ?? {}) } });
  if (!response.ok) { const body = (await response.json().catch(() => ({}))) as { detail?: string }; throw new Error(body.detail ?? "ANIMA could not complete that request"); }
  return response.json() as Promise<T>;
};
const allPages = async <T,>(path: string): Promise<T[]> => {
  const items: T[] = [];
  let cursor: string | null = null;
  do {
    const separator = path.includes("?") ? "&" : "?";
    const page: { items: T[]; next_cursor: string | null } = await api<{ items: T[]; next_cursor: string | null }>(
      `${path}${separator}limit=50${cursor ? `&cursor=${encodeURIComponent(cursor)}` : ""}`,
    );
    items.push(...page.items);
    cursor = page.next_cursor;
  } while (cursor);
  return items;
};
function StatusPill({ status }: { status: Status | string }) { return <span className={`status status-${status.toLowerCase().replaceAll("/", "-")}`}>{status.replaceAll("_", " ")}</span>; }
function Card({ title, children, className = "" }: { title: string; children: ReactNode; className?: string }) { return <section className={`card ${className}`}><div className="card-heading"><h2>{title}</h2></div>{children}</section>; }
function OutcomeNotice({ outcome }: { outcome: MutationOutcome | null }) { if (!outcome) return null; const tone = outcome.status === "SUCCEEDED" ? "success" : ["DENIED", "REQUIRE_CONFIRMATION", "REQUIRE_STRONGER_AUTH"].includes(outcome.status) ? "warning" : "error"; return <div className={`notice outcome ${tone}`} role="status" aria-live="polite"><strong>{outcome.status.replaceAll("_", " ")}</strong><span>{outcome.detail ?? outcome.reason ?? outcome.operation}</span></div>; }
function useMutation(csrf: string, refresh: () => Promise<void>, setError: (value: string) => void, setOutcome: (value: MutationOutcome) => void) {
  return async (path: string, payload: Record<string, unknown> = {}): Promise<MutationOutcome | null> => { try { setError(""); const result = await api<MutationOutcome>(path, { method: "POST", body: JSON.stringify({ payload }), headers: { "Content-Type": "application/json", "X-Anima-CSRF": csrf, Origin: window.location.origin } }); await refresh(); setOutcome(result); return result; } catch (err) { setError(err instanceof Error ? err.message : "ANIMA could not complete that request"); return null; } };
}

function App() {
  const [bootstrap, setBootstrap] = useState<Bootstrap | null>(null); const [home, setHome] = useState<Home | null>(null); const [settings, setSettings] = useState<Settings | null>(null); const [capabilities, setCapabilities] = useState<Capability[]>([]); const [integrations, setIntegrations] = useState<Integration[]>([]); const [devices, setDevices] = useState<ProviderDevice[]>([]); const [spaces, setSpaces] = useState<Space[]>([]); const [alertPolicies, setAlertPolicies] = useState<AlertPolicy[]>([]); const [alertEvents, setAlertEvents] = useState<AlertEvent[]>([]); const [alertNextCursor, setAlertNextCursor] = useState<string | null>(null); const [alertLoading, setAlertLoading] = useState(false); const [notificationRoutes, setNotificationRoutes] = useState<NotificationRoute[]>([]); const [backups, setBackups] = useState<BackupRecord[]>([]); const [scenes, setScenes] = useState<Scene[]>([]); const [automations, setAutomations] = useState<Automation[]>([]); const [preferences, setPreferences] = useState<Preference[]>([]); const [tab, setTab] = useState("Home"); const [message, setMessage] = useState(""); const [reply, setReply] = useState(""); const [conversationStatus, setConversationStatus] = useState<string | null>(null); const [error, setError] = useState(""); const [outcome, setOutcome] = useState<MutationOutcome | null>(null);
  const refreshGeneration = useRef(0);
  const refresh = async () => { const generation = ++refreshGeneration.current; try { setError(""); const [b, h, c, i, s, d, p, a, ae, n, backupsResult, scenesResult, automationsResult, preferencesResult] = await Promise.all([api<Bootstrap>("/api/v1/bootstrap"), api<Home>("/api/v1/home"), api<{ items: Capability[] }>("/api/v1/capabilities"), api<{ items: Integration[] }>("/api/v1/integrations"), api<{ settings: Settings }>("/api/v1/settings"), api<{ status: string; items: ProviderDevice[] }>("/api/v1/devices"), api<{ items: Space[] }>("/api/v1/places"), api<{ items: AlertPolicy[] }>("/api/v1/alerts/policies"), api<Page<AlertEvent>>("/api/v1/alerts/events"), api<{ items: NotificationRoute[] }>("/api/v1/notifications/routes"), api<{ items: BackupRecord[] }>("/api/v1/backups"), api<{ items: Scene[] }>("/api/v1/scenes"), api<{ items: Automation[] }>("/api/v1/automations"), api<{ items: Preference[] }>("/api/v1/preferences")]); if (generation !== refreshGeneration.current) return; setBootstrap(b); setHome(h); setCapabilities(c.items); setIntegrations(i.items); setSettings(s.settings); setDevices(d.items); setSpaces(p.items); setAlertPolicies(a.items); setAlertEvents(ae.items); setAlertNextCursor(ae.next_cursor); setNotificationRoutes(n.items); setBackups(backupsResult.items); setScenes(scenesResult.items); setAutomations(automationsResult.items); setPreferences(preferencesResult.items); } catch (err) { if (generation === refreshGeneration.current) setError(err instanceof Error ? err.message : "Anima is unavailable"); } };
  const loadOlderAlerts = async () => { if (!alertNextCursor || alertLoading) return; setAlertLoading(true); try { setError(""); const page = await api<Page<AlertEvent>>(`/api/v1/alerts/events?limit=50&cursor=${encodeURIComponent(alertNextCursor)}`); setAlertEvents((current) => [...current, ...page.items]); setAlertNextCursor(page.next_cursor); } catch (err) { setError(err instanceof Error ? err.message : "ANIMA could not load older alerts"); } finally { setAlertLoading(false); } };
  useEffect(() => { void refresh(); }, []);
  useEffect(() => { if (!bootstrap) return; const events = new EventSource("/api/v1/events"); const invalidate = () => void refresh(); ["home.invalidated", "tasks.changed", "calendar.changed", "alerts.changed", "activity.changed", "conversation.completed", "capabilities.changed", "preferences.changed", "refresh.required"].forEach((name) => events.addEventListener(name, invalidate)); return () => events.close(); }, [bootstrap]);
  useEffect(() => { if (!settings) return; const root = document.documentElement; root.dataset.appearance = settings.appearance; root.dataset.accent = settings.accent; root.dataset.density = settings.density; root.dataset.textScale = settings.text_scale; root.dataset.reducedMotion = settings.reduced_motion ? "true" : "false"; root.dataset.displayMode = settings.display_mode; }, [settings]);
  const send = async () => { if (!message.trim() || !bootstrap) return; try { setError(""); setConversationStatus("SENDING"); const result = await api<{ response: string; disposition?: string; request_id?: string }>("/api/v1/conversation", { method: "POST", body: JSON.stringify({ text: message.trim() }), headers: { "Content-Type": "application/json", "X-Anima-CSRF": bootstrap.csrf_token, Origin: window.location.origin } }); setReply(result.response); setMessage(""); if (result.disposition === "QUEUED_FOR_SENTRY" && result.request_id) { setConversationStatus("WAITING_FOR_SENTRY"); for (let attempt = 0; attempt < 120; attempt += 1) { await new Promise((resolve) => window.setTimeout(resolve, 1000)); const current = await api<ConversationResult>(`/api/v1/conversation/${result.request_id}`); if (["COMPLETED", "NO_ACTION", "FAILED", "UNKNOWN_RESULT", "RECOVERY_REQUIRED", "CANCELLED", "RESPONSE", "UNAVAILABLE"].includes(current.status) || current.available) { setConversationStatus(current.status); setReply(current.response ?? current.detail ?? "SENTRY completed without a retained live response."); break; } } } else { setConversationStatus(null); } } catch (err) { setConversationStatus("UNAVAILABLE"); setError(err instanceof Error ? err.message : "Anima could not respond"); } };
  const mutate = useMutation(bootstrap?.csrf_token ?? "", refresh, setError, setOutcome); const greeting = useMemo(() => bootstrap ? `Good evening, ${bootstrap.identity.display_name}.` : "Connecting to Anima…", [bootstrap]);
  if (!bootstrap || !home || !settings) return <main className="shell centered"><div className="brand-mark">A</div><h1>Anima</h1><p>{error || "Connecting to your home…"}</p>{error && <button onClick={() => void refresh()}>Try again</button>}</main>;
  const degraded = capabilities.some((item) => item.state === "degraded" || item.state === "unavailable"); const nav = ["Home", "Devices", "Spaces", "Scenes", "Automations", "Alerts", "Notifications", "Anima", "Tasks & Calendar", "Activity", "Capabilities", "Integrations", "Backups", "Preferences", "Settings"];
  if (tab === "Alerts") return <div className="app-shell"><aside className="sidebar"><div className="brand"><div className="brand-mark">A</div><div><strong>Anima</strong><small>home intelligence</small></div></div><nav aria-label="Primary navigation">{nav.map((item) => <button key={item} className={tab === item ? "nav-item active" : "nav-item"} onClick={() => setTab(item)}>{item}</button>)}</nav><div className="sidebar-footer"><StatusPill status={degraded ? "degraded" : "online"} /><span>{degraded ? "Some capabilities degraded" : "Core online"}</span></div></aside><main className="content"><header className="topbar"><div><p className="eyebrow">{bootstrap.household.name}</p><h1>Alerts</h1></div><button className="avatar" aria-label="Current household member">H</button></header><OutcomeNotice outcome={outcome} />{error && <div className="notice error" role="alert">{error}</div>}<AlertPoliciesView policies={alertPolicies} devices={devices} mutate={mutate} events={alertEvents} nextCursor={alertNextCursor} loading={alertLoading} loadOlder={loadOlderAlerts} /></main></div>;
  return <div className="app-shell"><aside className="sidebar"><div className="brand"><div className="brand-mark">A</div><div><strong>Anima</strong><small>home intelligence</small></div></div><nav aria-label="Primary navigation">{nav.map((item) => <button key={item} className={tab === item ? "nav-item active" : "nav-item"} onClick={() => setTab(item)}>{item}</button>)}</nav><div className="sidebar-footer"><StatusPill status={degraded ? "degraded" : "online"} /><span>{degraded ? "Some capabilities degraded" : "Core online"}</span></div></aside><main className="content"><header className="topbar"><div><p className="eyebrow">{bootstrap.household.name}</p><h1>{tab === "Home" ? greeting : tab}</h1></div><button className="avatar" aria-label="Current household member">H</button></header><OutcomeNotice outcome={outcome} />{error && <div className="notice error" role="alert">{error}</div>}{tab === "Home" && <HomeView home={home} settings={settings} mutate={mutate} reply={reply} />}{tab === "Devices" && <DevicesView devices={devices} rooms={home.rooms} mutate={mutate} />}{tab === "Spaces" && <SpacesView spaces={spaces} mutate={mutate} />}{tab === "Scenes" && <ScenesView scenes={scenes} controls={home.controls} mutate={mutate} />}{tab === "Automations" && <AutomationsView automations={automations} devices={devices} controls={home.controls} mutate={mutate} />}{tab === "Alerts" && <AlertPoliciesView policies={alertPolicies} devices={devices} mutate={mutate} events={alertEvents} nextCursor={alertNextCursor} loading={alertLoading} loadOlder={loadOlderAlerts} />}{tab === "Notifications" && <NotificationRoutesView routes={notificationRoutes} mutate={mutate} />}{tab === "Anima" && <Card title="Talk with SENTRY" className="conversation"><p className="muted">Ask SENTRY about your home. ANIMA supplies the household Truth, policy, and verified actions.</p><Composer message={message} setMessage={setMessage} send={send} />{conversationStatus && <p className="muted" role="status">SENTRY · {conversationStatus.replaceAll("_", " ")}</p>}{reply && <div className="reply" aria-live="polite"><strong>SENTRY</strong><p>{reply}</p></div>}</Card>}{tab === "Tasks & Calendar" && <TaskCalendar mutate={mutate} />}{tab === "Activity" && <Card title="Recent activity"><ul className="clean-list">{home.activity.map((item, index) => <li key={`${item.summary}-${index}`}><span>{item.summary}</span><StatusPill status={item.status} /></li>)}</ul></Card>}{tab === "Capabilities" && <Capabilities items={capabilities} />}{tab === "Integrations" && <ManagedIntegrationsView items={integrations} mutate={mutate} />}{tab === "Backups" && <BackupsView backups={backups} mutate={mutate} />}{tab === "Preferences" && <PreferencesView preferences={preferences} mutate={mutate} />}{tab === "Settings" && <SettingsPanel value={settings} csrf={bootstrap.csrf_token} onSaved={setSettings} setError={setError} setOutcome={setOutcome} />}</main></div>;
}

function HomeView({ home, settings, mutate, reply }: { home: Home; settings: Settings; mutate: (path: string, payload?: Record<string, unknown>) => Promise<MutationOutcome | null>; reply: string }) {
  const widgets: Record<string, ReactNode> = {
    status: <Card title="At a glance" className="hero"><p className="hero-copy">{home.household.summary}</p><p className="muted">{home.health.summary}</p><div className="metric-row"><div><span>Presence</span><strong>{home.presence.people[0]?.state ?? "unknown"}</strong></div><div><span>Security</span><strong><StatusPill status={home.security.status} /></strong></div><div><span>Weather</span><strong><StatusPill status={home.weather.status} /></strong></div><div><span>Health</span><strong><StatusPill status={home.health.status} /></strong></div></div></Card>,
    presence: <Card title="People at home"><ul className="clean-list">{home.presence.people.map((person) => <li key={person.name}><span><span className="person-dot" />{person.name}</span><StatusPill status={person.state} /></li>)}</ul></Card>,
    weather: <Card title="Weather"><p className="muted">{home.weather.summary}</p></Card>,
    agenda: <Card title="Coming up"><ul className="clean-list">{home.calendar.map((event) => <li key={event.event_id}><span>{event.title}</span><time>{new Date(event.start_at).toLocaleString([], { weekday: "short", hour: "numeric", minute: "2-digit" })}</time></li>)}</ul></Card>,
    tasks: <Card title="Things to do"><ul className="clean-list">{home.tasks.map((task) => <li key={task.task_id}><span>{task.title}</span><StatusPill status={task.status} /></li>)}</ul></Card>,
    controls: <Card title="Home controls"><ul className="clean-list">{home.controls.length ? home.controls.map((control) => <li key={control.control_id}><span>{control.label}<small className="muted control-state">{control.state}</small></span><span className="button-row"><button onClick={() => void mutate(`/api/v1/controls/${control.control_id}`, { desired_on: true })}>On</button><button onClick={() => void mutate(`/api/v1/controls/${control.control_id}`, { desired_on: false })}>Off</button></span></li>) : <li className="muted">No commissioned controls are available.</li>}</ul></Card>,
    conversation: <Card title="Anima"><p className="muted">{reply || "I’m here when you need a hand."}</p></Card>,
    activity: <Card title="Activity"><ul className="clean-list">{home.activity.length ? home.activity.map((item, index) => <li key={`${item.summary}-${index}`}><span>{item.summary}</span><StatusPill status={item.status} /></li>) : <li className="muted">No household activity recorded.</li>}</ul></Card>,
    household: <Card title="Rooms & devices"><div className="room-list">{home.rooms.length ? home.rooms.map((room) => <div className="room" key={room.place_id}><strong>{room.name}</strong><small className="muted">{room.kind}</small>{room.devices.length ? <ul className="clean-list nested-list">{room.devices.map((device) => <li key={device.device_id}><span>{device.name}<small className="muted">{device.kind}</small></span><StatusPill status={device.state} /></li>)}</ul> : <p className="muted">No commissioned devices in this place.</p>}</div>) : <p className="muted">No commissioned rooms or devices are available.</p>}</div></Card>,
    reports: <Card title="Notifications & recent actions"><h3>Notifications</h3><ul className="clean-list">{home.notifications.length ? home.notifications.map((item) => <li key={item.notification_id}><span>{item.summary}<small className="muted">{item.importance ?? "household"}</small></span><StatusPill status={item.status} /></li>) : <li className="muted">No notifications recorded.</li>}</ul><h3 className="subheading">Reports</h3><ul className="clean-list">{home.reports.length ? home.reports.map((item) => <li key={item.report_id}><span>{item.summary}<small className="muted">{item.disposition ?? "No disposition"}</small></span><StatusPill status={item.status} /></li>) : <li className="muted">No episode reports recorded.</li>}</ul><h3 className="subheading">Recent actions</h3><ul className="clean-list">{home.recent_actions.length ? home.recent_actions.map((item) => <li key={item.action_id}><span>{item.tool_id}<small className="muted">{item.detail}</small></span><StatusPill status={item.status} /></li>) : <li className="muted">No governed actions recorded.</li>}</ul>{home.pending_approvals.length > 0 && <div className="pending-approval"><strong>Pending confirmation</strong>{home.pending_approvals.map((approval) => <div className="notice warning" key={approval.approval_id}><span>{approval.summary}<small className="muted">Expires {new Date(approval.expires_at).toLocaleTimeString()}</small></span><span className="button-row"><button onClick={() => void mutate(`/api/v1/approvals/${approval.approval_id}`, { decision: "APPROVE" })}>Approve</button><button onClick={() => void mutate(`/api/v1/approvals/${approval.approval_id}`, { decision: "REJECT" })}>Reject</button></span></div>)}</div>}</Card>,
    health: <Card title="System health"><p className="muted">{home.health.summary}</p><StatusPill status={home.health.status} />{home.health.unavailable.length > 0 && <p className="muted"><strong>Unavailable:</strong> {home.health.unavailable.join(", ")}</p>}{home.health.degraded.length > 0 && <p className="muted"><strong>Degraded:</strong> {home.health.degraded.join(", ")}</p>}</Card>,
  };
  const order = settings.widget_order.filter((id) => settings.visible_widgets.includes(id));
  return <div className="dashboard">{order.map((id) => <div className="widget" data-widget={id} key={id}>{widgets[id]}</div>)}</div>;
}
function SpacesView({ spaces, mutate }: { spaces: Space[]; mutate: (path: string, payload?: Record<string, unknown>) => Promise<MutationOutcome | null> }) {
  const root = spaces.find((space) => space.kind === "HOUSEHOLD");
  const parents = spaces.filter((space) => ["HOUSEHOLD", "PROPERTY", "BUILDING", "FLOOR", "ROOM", "ZONE", "OUTSIDE"].includes(space.kind));
  const [name, setName] = useState(""); const [kind, setKind] = useState<"ROOM" | "ZONE">("ROOM"); const [parentId, setParentId] = useState(root?.place_id ?? ""); const [editing, setEditing] = useState<string | null>(null); const [editName, setEditName] = useState(""); const [editParentId, setEditParentId] = useState("");
  useEffect(() => { if (!parentId && root) setParentId(root.place_id); }, [parentId, root?.place_id]);
  const create = async (event: React.FormEvent) => { event.preventDefault(); const result = await mutate("/api/v1/places/create", { name, kind, parent_id: parentId }); if (result?.status === "SUCCEEDED") { setName(""); } };
  const saveName = async (event: React.FormEvent, space: Space) => { event.preventDefault(); const result = await mutate("/api/v1/places/rename", { place_id: space.place_id, name: editName }); if (result?.status === "SUCCEEDED") setEditing(null); };
  const move = async (event: React.FormEvent, space: Space) => { event.preventDefault(); if (!editParentId || editParentId === space.parent_id) { setEditing(null); return; } const result = await mutate("/api/v1/places/move", { place_id: space.place_id, parent_id: editParentId }); if (result?.status === "SUCCEEDED") setEditing(null); };
  const beginEdit = (space: Space) => { setEditing(space.place_id); setEditName(space.name); setEditParentId(space.parent_id ?? root?.place_id ?? ""); };
  const descendantsOf = (placeId: string) => { const descendants = new Set<string>(); let changed = true; while (changed) { changed = false; spaces.forEach((candidate) => { if (candidate.parent_id && (candidate.parent_id === placeId || descendants.has(candidate.parent_id)) && !descendants.has(candidate.place_id)) { descendants.add(candidate.place_id); changed = true; } }); } return descendants; };
  return <div className="dashboard"><Card title="Create a room or zone"><p className="muted">ANIMA owns the canonical household map. Create a place here before assigning a newly paired device; Home Assistant remains behind the integration boundary.</p><form className="stack" onSubmit={(event) => void create(event)}><label>Name<input required maxLength={120} value={name} onChange={(event) => setName(event.target.value)} /></label><label>Type<select value={kind} onChange={(event) => setKind(event.target.value as "ROOM" | "ZONE")}><option value="ROOM">Room</option><option value="ZONE">Zone</option></select></label><label>Contained in<select required value={parentId} onChange={(event) => setParentId(event.target.value)}>{parents.map((parent) => <option key={parent.place_id} value={parent.place_id}>{parent.name} · {parent.kind.toLowerCase()}</option>)}</select></label><button type="submit" disabled={!parentId}>Create place</button></form></Card><Card title="Household places"><p className="muted">Rooms and zones are canonical ANIMA resources and are available to device commissioning. A place can be moved only within this household and removed only when empty.</p>{spaces.length ? <ul className="clean-list list-spaced">{spaces.map((space) => <li className="space-row" key={space.place_id}>{editing === space.place_id ? <div className="stack"><form className="stack" onSubmit={(event) => void saveName(event, space)}><label>Name<input required maxLength={120} aria-label={`Name for ${space.name}`} value={editName} onChange={(event) => setEditName(event.target.value)} /><button type="submit">Save name</button></label></form><form className="stack" onSubmit={(event) => void move(event, space)}><label>Contained in<select required aria-label={`Parent for ${space.name}`} value={editParentId} onChange={(event) => setEditParentId(event.target.value)}>{parents.filter((parent) => parent.place_id !== space.place_id && !descendantsOf(space.place_id).has(parent.place_id)).map((parent) => <option key={parent.place_id} value={parent.place_id}>{parent.name} · {parent.kind.toLowerCase()}</option>)}</select><button type="submit">Move place</button></label></form><button type="button" onClick={() => setEditing(null)}>Done</button></div> : <><span><strong>{space.name}</strong><small className="muted">{space.kind}{space.parent_id ? ` · in ${spaces.find((parent) => parent.place_id === space.parent_id)?.name ?? "household"}` : ""}</small></span>{["ROOM", "ZONE"].includes(space.kind) && <span className="button-row"><button onClick={() => beginEdit(space)}>Manage</button><button onClick={() => { if (window.confirm(`Remove ${space.name}? It must be empty.`)) void mutate("/api/v1/places/remove", { place_id: space.place_id }); }}>Remove</button></span>}</>}</li>)}</ul> : <p className="muted">No commissioned household places are available.</p>}</Card></div>;
}
function DevicesView({ devices, rooms, mutate }: { devices: ProviderDevice[]; rooms: Room[]; mutate: (path: string, payload?: Record<string, unknown>) => Promise<MutationOutcome | null> }) {
  const [duration, setDuration] = useState("60");
  const [commissioningId, setCommissioningId] = useState<string | null>(null);
  const [editing, setEditing] = useState<ProviderDevice | null>(null);
  const [name, setName] = useState("");
  const [placeId, setPlaceId] = useState(rooms[0]?.place_id ?? "");
  const discovered = devices.filter((item) => item.external_object_kind === "device" && item.present);
  const commissioned = discovered.filter((item) => item.metadata.mapping_status === "MAPPED");
  const beginCommission = (item: ProviderDevice) => {
    setEditing(null);
    setCommissioningId(item.device_handle);
    setName(String(item.metadata.name_by_user ?? item.metadata.name ?? "New device"));
    setPlaceId(rooms[0]?.place_id ?? "");
  };
  const beginEdit = (item: ProviderDevice) => {
    const resourceId = String(item.metadata.canonical_target_id ?? "");
    const currentRoom = rooms.find((room) => room.devices.some((device) => device.device_id === resourceId));
    setCommissioningId(null);
    setEditing(item);
    setName(String(item.metadata.name_by_user ?? item.metadata.name ?? "New device"));
    setPlaceId(currentRoom?.place_id ?? rooms[0]?.place_id ?? "");
  };
  const saveDevice = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!resourceId) return;
    const renamed = await mutate("/api/v1/devices/rename", { resource_id: resourceId, name });
    if (renamed?.status !== "SUCCEEDED") return;
    const moved = await mutate("/api/v1/devices/reassign", { resource_id: resourceId, place_id: placeId });
    if (moved?.status === "SUCCEEDED") setEditing(null);
  };
  const resourceId = editing ? String(editing.metadata.canonical_target_id ?? "") : "";
  return <div className="dashboard">
    <Card title="Add a device"><p className="muted">Put the device in pairing mode, then open a short Zigbee join window. ANIMA will refresh Home Assistant’s registry and let you place the discovered device here.</p><div className="stack"><label>Pairing window (seconds)<input type="number" min="1" max="120" value={duration} onChange={(event) => setDuration(event.target.value)} /></label><div className="button-row"><button onClick={() => void mutate("/api/v1/devices/permit-pairing", { duration_seconds: Number(duration) })}>Open pairing window</button><button onClick={() => void mutate("/api/v1/devices/refresh")}>Refresh discovered devices</button></div></div></Card>
    <Card title="Discovered Home Assistant devices"><p className="muted">Only registry objects from the commissioned Home Assistant instance appear here. ANIMA owns the household name, room assignment, current-state projection, and governed controls; Home Assistant remains behind the integration boundary.</p>{discovered.length ? <ul className="clean-list list-spaced">{discovered.map((item) => { const mapped = item.metadata.mapping_status === "MAPPED"; const resourceId = String(item.metadata.canonical_target_id ?? ""); const power = item.capabilities?.find((capability) => capability.type === "power.set" && capability.writable); const label = String(item.metadata.name_by_user ?? item.metadata.name ?? "Unnamed device"); const observed = item.observed_at ? new Date(item.observed_at).toLocaleString() : "No current observation"; return <li className="device-row" key={item.device_handle}><span><strong>{label}</strong><small className="muted">{item.metadata.manufacturer ?? ""}{item.metadata.model ? ` · ${item.metadata.model}` : ""} · {mapped ? "Commissioned" : "Needs a room"}</small>{mapped && <small className="device-state">State: {item.state ?? "UNKNOWN"} · {item.truth_status ?? "UNKNOWN"}</small>}{mapped && <small className="muted">Observed: {observed}</small>}{mapped && item.capabilities && item.capabilities.length > 0 && <small className="muted">Capabilities: {item.capabilities.map((capability) => capability.type).join(", ")}</small>}</span><span className="button-row">{mapped && power && resourceId && <><button aria-label={`Turn ${label} on`} onClick={() => void mutate(`/api/v1/controls/${resourceId}`, { desired_on: true })}>On</button><button aria-label={`Turn ${label} off`} onClick={() => void mutate(`/api/v1/controls/${resourceId}`, { desired_on: false })}>Off</button></>}{mapped ? <button onClick={() => beginEdit(item)}>Manage</button> : <button onClick={() => beginCommission(item)}>Add to Anima</button>}</span></li>; })}</ul> : <p className="muted">No discovered devices are available. Open pairing, add the device, then refresh.</p>}
      {commissioningId && <form className="stack commission-form" onSubmit={(event) => { event.preventDefault(); void mutate("/api/v1/devices/commission", { device_handle: commissioningId, name, place_id: placeId }).then((result) => { if (result?.status === "SUCCEEDED") setCommissioningId(null); }); }}><h3>Place device in Anima</h3><label>Display name<input required maxLength={120} value={name} onChange={(event) => setName(event.target.value)} /></label><label>Room<select required value={placeId} onChange={(event) => setPlaceId(event.target.value)}><option value="" disabled>Select a room</option>{rooms.map((room) => <option key={room.place_id} value={room.place_id}>{room.name}</option>)}</select></label><div className="button-row"><button type="submit" disabled={!placeId}>Commission device</button><button type="button" onClick={() => setCommissioningId(null)}>Cancel</button></div></form>}
      {editing && <form className="stack commission-form" onSubmit={(event) => void saveDevice(event)}><h3>Manage commissioned device</h3><p className="muted">These changes update ANIMA’s canonical household model. They do not rename or delete the Home Assistant registry object.</p><label>Display name<input required maxLength={120} value={name} onChange={(event) => setName(event.target.value)} /></label><label>Room<select required value={placeId} onChange={(event) => setPlaceId(event.target.value)}><option value="" disabled>Select a room</option>{rooms.map((room) => <option key={room.place_id} value={room.place_id}>{room.name}</option>)}</select></label><div className="button-row"><button type="submit" disabled={!placeId || !resourceId}>Save device</button><button type="button" onClick={() => { if (resourceId) void mutate("/api/v1/devices/retire", { resource_id: resourceId }).then((result) => { if (result?.status === "SUCCEEDED") setEditing(null); }); }}>Remove from Anima</button><button type="button" onClick={() => setEditing(null)}>Cancel</button></div></form>}
    </Card>
  </div>;
}
function Composer({ message, setMessage, send }: { message: string; setMessage: (value: string) => void; send: () => Promise<void> }) { return <div className="composer"><label htmlFor="message">Message Anima</label><textarea id="message" value={message} onChange={(event) => setMessage(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); void send(); } }} placeholder="What would you like to know?" /><button onClick={() => void send()}>Send</button></div>; }
function NotificationRoutesView({ routes, mutate }: { routes: NotificationRoute[]; mutate: (path: string, payload?: Record<string, unknown>) => Promise<MutationOutcome | null> }) {
  const current = routes[0];
  const [label, setLabel] = useState(current?.label ?? "Household notifications");
  const [minimumPriority, setMinimumPriority] = useState(current?.minimum_priority ?? 70);
  const [enabled, setEnabled] = useState(current?.enabled ?? true);
  useEffect(() => { setLabel(current?.label ?? "Household notifications"); setMinimumPriority(current?.minimum_priority ?? 70); setEnabled(current?.enabled ?? true); }, [current?.route_id, current?.version]);
  const save = async (event: React.FormEvent) => { event.preventDefault(); const payload: Record<string, unknown> = { label, minimum_priority: minimumPriority, enabled }; if (current) { payload.route_id = current.route_id; payload.expected_version = current.version; } await mutate("/api/v1/notifications/routes", payload); };
  const destinationLabel = current?.destination === "server_configured" ? "Server configured" : current?.destination ?? "Server configured";
  return <div className="dashboard notification-routes"><Card title="Notification route"><p className="muted">Choose when the configured household notification route is eligible. ANIMA keeps the provider destination and credentials on the server.</p><form className="stack" onSubmit={(event) => void save(event)}><label>Route label<input required maxLength={80} value={label} onChange={(event) => setLabel(event.target.value)} /></label><label>Minimum alert priority<input required type="number" min="0" max="100" value={minimumPriority} onChange={(event) => setMinimumPriority(Number(event.target.value))} /></label><label className="checkbox"><input type="checkbox" checked={enabled} onChange={(event) => setEnabled(event.target.checked)} /> Route enabled</label><button type="submit">{current ? "Save route" : "Create route"}</button></form></Card><Card title="Delivery boundary"><dl className="settings-grid"><dt>Provider</dt><dd><strong>{current?.provider ?? "ntfy"}</strong></dd><dt>Destination</dt><dd><strong>{destinationLabel}</strong></dd><dt>Status</dt><dd><StatusPill status={current ? (current.enabled ? "ACTIVE" : "DISABLED") : "NOT_CONFIGURED"} /></dd></dl><p className="muted">A provider acceptance is not the same as a confirmed human receipt. Delivery results remain governed external observations.</p></Card></div>;
}

function AlertPoliciesView({ policies, devices, mutate, events, nextCursor, loading, loadOlder }: { policies: AlertPolicy[]; devices: ProviderDevice[]; mutate: (path: string, payload?: Record<string, unknown>) => Promise<MutationOutcome | null>; events: AlertEvent[]; nextCursor: string | null; loading: boolean; loadOlder: () => Promise<void> }) {
  const resources = devices.filter((item) => item.present && item.metadata.canonical_target_id).map((item) => ({ id: String(item.metadata.canonical_target_id), label: String(item.metadata.name_by_user ?? item.metadata.name ?? "Unnamed device") }));
  const blank: Omit<AlertPolicy, "policy_id" | "version"> = { event_type: "senseguard.event", timezone: "America/New_York", start_local: "00:00", end_local: "05:00", priority: 90, guaranteed_attention: true, delivery_mode: "SENTRY_COGNITION", enabled: true, resource_ids: resources[0] ? [resources[0].id] : [] };
  const [draft, setDraft] = useState(blank); const [editing, setEditing] = useState<AlertPolicy | null>(null);
  useEffect(() => { if (!editing && resources[0] && draft.resource_ids.length === 0) setDraft({ ...draft, resource_ids: [resources[0].id] }); }, [resources.length, editing]);
  const edit = (policy: AlertPolicy) => { setEditing(policy); setDraft({ event_type: policy.event_type, timezone: policy.timezone, start_local: policy.start_local.slice(0, 5), end_local: policy.end_local.slice(0, 5), priority: policy.priority, guaranteed_attention: policy.guaranteed_attention, delivery_mode: policy.delivery_mode, enabled: policy.enabled, resource_ids: policy.resource_ids }); };
  const reset = () => { setEditing(null); setDraft({ ...blank, resource_ids: resources[0] ? [resources[0].id] : [] }); };
  const save = async (event: React.FormEvent) => { event.preventDefault(); const payload: Record<string, unknown> = { ...draft }; if (editing) { payload.policy_id = editing.policy_id; payload.expected_version = editing.version; } const result = await mutate("/api/v1/alerts/policies", payload); if (result?.status === "SUCCEEDED") reset(); };
  const toggle = (policy: AlertPolicy) => void mutate("/api/v1/alerts/policies", { policy_id: policy.policy_id, expected_version: policy.version, resource_ids: policy.resource_ids, event_type: policy.event_type, timezone: policy.timezone, start_local: policy.start_local.slice(0, 5), end_local: policy.end_local.slice(0, 5), priority: policy.priority, guaranteed_attention: policy.guaranteed_attention, delivery_mode: policy.delivery_mode, enabled: !policy.enabled });
  return <div className="dashboard"><Card title={editing ? "Edit alert policy" : "Create an alert policy"}><p className="muted">Choose when a commissioned SenseGuard resource should bring the event to SENTRY’s attention. This is a typed policy, not a raw Home Assistant automation.</p>{resources.length ? <form className="stack" onSubmit={(event) => void save(event)}><label>SenseGuard resources<select multiple required value={draft.resource_ids} onChange={(event) => setDraft({ ...draft, resource_ids: Array.from(event.target.selectedOptions, (option) => option.value) })}>{resources.map((resource) => <option key={resource.id} value={resource.id}>{resource.label}</option>)}</select></label><label>Event type<input required maxLength={120} value={draft.event_type} onChange={(event) => setDraft({ ...draft, event_type: event.target.value })} /></label><div className="form-grid"><label>From<input required type="time" value={draft.start_local} onChange={(event) => setDraft({ ...draft, start_local: event.target.value })} /></label><label>Until<input required type="time" value={draft.end_local} onChange={(event) => setDraft({ ...draft, end_local: event.target.value })} /></label><label>Priority<input required type="number" min="0" max="100" value={draft.priority} onChange={(event) => setDraft({ ...draft, priority: Number(event.target.value) })} /></label><label>Timezone<input required maxLength={64} value={draft.timezone} onChange={(event) => setDraft({ ...draft, timezone: event.target.value })} /></label></div><label>Delivery<select value={draft.delivery_mode} onChange={(event) => setDraft({ ...draft, delivery_mode: event.target.value as AlertPolicy["delivery_mode"] })}><option value="SENTRY_COGNITION">SENTRY cognition</option><option value="NOTIFICATION">Notification</option></select></label><label className="checkbox"><input type="checkbox" checked={draft.guaranteed_attention} onChange={(event) => setDraft({ ...draft, guaranteed_attention: event.target.checked })} /> Guaranteed attention</label><label className="checkbox"><input type="checkbox" checked={draft.enabled} onChange={(event) => setDraft({ ...draft, enabled: event.target.checked })} /> Enabled</label><div className="button-row"><button type="submit">{editing ? "Save changes" : "Create policy"}</button>{editing && <button type="button" onClick={reset}>Cancel</button>}</div></form> : <p className="muted">No canonical SenseGuard resources are commissioned yet. Add and commission a device first.</p>}</Card><Card title="Configured policies"><p className="muted">Policies remain household-scoped and versioned. Disabling preserves their history.</p>{policies.length ? <ul className="clean-list list-spaced">{policies.map((policy) => <li className="policy-row" key={policy.policy_id}><span><strong>{policy.event_type}</strong><small className="muted">{policy.start_local.slice(0, 5)}–{policy.end_local.slice(0, 5)} · priority {policy.priority} · v{policy.version}</small></span><span className="button-row"><StatusPill status={policy.enabled ? "ACTIVE" : "DISABLED"} /><button onClick={() => edit(policy)}>Edit</button><button onClick={() => toggle(policy)}>{policy.enabled ? "Disable" : "Enable"}</button></span></li>)}</ul> : <p className="muted">No alert policies configured.</p>}</Card><Card title="Alert inbox"><p className="muted">Matched SenseGuard events recorded by ANIMA. Timestamps are source observations; delivery status is not a human-receipt claim.</p>{events.length ? <ul className="clean-list list-spaced">{events.map((event) => <li className="alert-row" key={event.alert_id}><span><strong>{event.resource_name}</strong><small className="muted">{event.event_type} · {new Date(event.occurred_at).toLocaleString()} · priority {event.priority}</small><small className="muted">{event.delivery_mode.replaceAll("_", " ")}</small></span><span className="button-row"><StatusPill status={event.delivery_status} /></span></li>)}</ul> : <p className="muted">No matched SenseGuard events recorded yet.</p>}{nextCursor && <div className="button-row"><button type="button" onClick={() => void loadOlder()} disabled={loading}>{loading ? "Loading older alerts…" : "Load older alerts"}</button></div>}</Card></div>;
}
function inputDate(value: string) { const date = new Date(value); const offset = date.getTimezoneOffset() * 60_000; return new Date(date.getTime() - offset).toISOString().slice(0, 16); }
function TaskCalendar({ mutate }: { mutate: (path: string, payload?: Record<string, unknown>) => Promise<MutationOutcome | null> }) {
  const [title, setTitle] = useState(""); const [when, setWhen] = useState(""); const [note, setNote] = useState(""); const [eventTitle, setEventTitle] = useState(""); const [start, setStart] = useState(""); const [end, setEnd] = useState(""); const [editing, setEditing] = useState<string | null>(null); const [editTitle, setEditTitle] = useState(""); const [editStart, setEditStart] = useState(""); const [editEnd, setEditEnd] = useState("");
  const [tasks, setTasks] = useState<Task[]>([]); const [calendar, setCalendar] = useState<CalendarEvent[]>([]);
  const reload = async () => { const [taskItems, calendarItems] = await Promise.all([allPages<Task>("/api/v1/tasks"), allPages<CalendarEvent>("/api/v1/calendar")]); setTasks(taskItems); setCalendar(calendarItems); };
  useEffect(() => { void reload(); }, []);
  const runMutation = async (path: string, payload?: Record<string, unknown>) => { const result = await mutate(path, payload); await reload(); return result; };
  const edit = (event: CalendarEvent) => { setEditing(event.event_id); setEditTitle(event.title); setEditStart(inputDate(event.start_at)); setEditEnd(inputDate(event.end_at)); };
  return <div className="dashboard"><Card title="Tasks"><form className="stack" onSubmit={(event) => { event.preventDefault(); void runMutation("/api/v1/tasks", { title, when, note }).then((result) => { if (result?.status === "SUCCEEDED") { setTitle(""); setWhen(""); setNote(""); } }); }}><label>Reminder title<input required value={title} onChange={(event) => setTitle(event.target.value)} /></label><label>When<input required type="datetime-local" value={when} onChange={(event) => setWhen(event.target.value)} /></label><label>Note<input value={note} onChange={(event) => setNote(event.target.value)} /></label><button type="submit">Create task</button></form><ul className="clean-list list-spaced">{tasks.map((task) => <li key={task.task_id}><span>{task.title}<small className="muted">{task.next_run_at ? new Date(task.next_run_at).toLocaleString() : ""}</small></span><span className="button-row"><StatusPill status={task.status} />{task.status === "ACTIVE" && <><button onClick={() => void runMutation(`/api/v1/tasks/${task.task_id}/pause`)}>Pause</button><button onClick={() => void runMutation(`/api/v1/tasks/${task.task_id}/cancel`)}>Cancel</button></>}{task.status === "PAUSED" && <><button onClick={() => void runMutation(`/api/v1/tasks/${task.task_id}/resume`)}>Resume</button><button onClick={() => void runMutation(`/api/v1/tasks/${task.task_id}/cancel`)}>Cancel</button></>}</span></li>)}</ul></Card><Card title="Calendar"><form className="stack" onSubmit={(event) => { event.preventDefault(); void runMutation("/api/v1/calendar", { title: eventTitle, start_at: new Date(start).toISOString(), end_at: new Date(end).toISOString(), timezone: "UTC" }).then((result) => { if (result?.status === "SUCCEEDED") { setEventTitle(""); setStart(""); setEnd(""); } }); }}><label>Event title<input required value={eventTitle} onChange={(event) => setEventTitle(event.target.value)} /></label><label>Starts<input required type="datetime-local" value={start} onChange={(event) => setStart(event.target.value)} /></label><label>Ends<input required type="datetime-local" value={end} onChange={(event) => setEnd(event.target.value)} /></label><button type="submit">Create event</button></form><ul className="clean-list list-spaced">{calendar.map((event) => <li className="calendar-row" key={event.event_id}>{editing === event.event_id ? <form className="edit-form" onSubmit={(submit) => { submit.preventDefault(); void runMutation(`/api/v1/calendar/${event.event_id}/update`, { expected_version: event.version ?? 1, title: editTitle, start_at: new Date(editStart).toISOString(), end_at: new Date(editEnd).toISOString(), timezone: "UTC" }).then((result) => { if (result?.status === "SUCCEEDED") setEditing(null); }); }}><label>Title<input required value={editTitle} onChange={(input) => setEditTitle(input.target.value)} /></label><label>Starts<input required type="datetime-local" value={editStart} onChange={(input) => setEditStart(input.target.value)} /></label><label>Ends<input required type="datetime-local" value={editEnd} onChange={(input) => setEditEnd(input.target.value)} /></label><span className="button-row"><button type="submit">Save edit</button><button type="button" onClick={() => setEditing(null)}>Close</button></span></form> : <><span>{event.title}<small className="muted">{new Date(event.start_at).toLocaleString()}</small></span><span className="button-row"><StatusPill status={event.status} />{event.status === "ACTIVE" && <><button onClick={() => edit(event)}>Edit</button><button onClick={() => void runMutation(`/api/v1/calendar/${event.event_id}/cancel`, { expected_version: event.version ?? 1 })}>Cancel</button></>}</span></>}</li>)}</ul></Card></div>;
}
function PreferencesView({ preferences, mutate }: { preferences: Preference[]; mutate: (path: string, payload?: Record<string, unknown>) => Promise<MutationOutcome | null> }) {
  const [content, setContent] = useState("");
  const [category, setCategory] = useState<Preference["category"]>("other");
  const [editing, setEditing] = useState<Preference | null>(null);
  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    const result = await mutate(`/api/v1/preferences/${editing ? "update" : "create"}`, editing ? { preference_id: editing.preference_id, content, category } : { content, category });
    if (result?.status === "SUCCEEDED") { setContent(""); setCategory("other"); setEditing(null); }
  };
  const beginEdit = (preference: Preference) => { setEditing(preference); setContent(preference.content); setCategory(preference.category); };
  const cancel = () => { setEditing(null); setContent(""); setCategory("other"); };
  return <div className="dashboard"><Card title={editing ? "Correct a preference" : "Add a household preference"}><p className="muted">These explicit notes help ANIMA and SENTRY understand household choices. They never grant permission, change policy, or replace current device Truth.</p><form className="stack" onSubmit={(event) => void submit(event)}><label>Preference<textarea required maxLength={1000} value={content} onChange={(event) => setContent(event.target.value)} placeholder="Example: notify me immediately about SenseGuard events overnight" /></label><label>Category<select value={category} onChange={(event) => setCategory(event.target.value as Preference["category"])}>{["alerts", "comfort", "meals", "shopping", "privacy", "other"].map((item) => <option key={item} value={item}>{item}</option>)}</select></label><div className="button-row"><button type="submit">{editing ? "Save correction" : "Save preference"}</button>{editing && <button type="button" onClick={cancel}>Cancel</button>}</div></form></Card><Card title="Active household preferences"><p className="muted">Stored with explicit-input provenance and available to bounded household context.</p>{preferences.length ? <ul className="clean-list list-spaced">{preferences.map((preference) => <li className="preference-row" key={preference.preference_id}><span><strong>{preference.content}</strong><small className="muted">{preference.category} · {new Date(preference.created_at).toLocaleString()} · {preference.provenance?.kind ?? "EXPLICIT_INPUT"}</small></span><span className="button-row"><button onClick={() => beginEdit(preference)}>Edit</button><button onClick={() => void mutate("/api/v1/preferences/retract", { preference_id: preference.preference_id })}>Forget</button></span></li>)}</ul> : <p className="muted">No explicit preferences recorded.</p>}</Card></div>;
}
function SettingsPanel({ value, csrf, onSaved, setError, setOutcome }: { value: Settings; csrf: string; onSaved: (value: Settings) => void; setError: (value: string) => void; setOutcome: (value: MutationOutcome) => void }) {
  const [draft, setDraft] = useState(value); useEffect(() => setDraft(value), [value]); const update = <K extends keyof Settings>(key: K, next: Settings[K]) => setDraft({ ...draft, [key]: next }); const toggleWidget = (id: string) => update("visible_widgets", draft.visible_widgets.includes(id) ? draft.visible_widgets.filter((item) => item !== id) : [...draft.visible_widgets, id]); const moveWidget = (id: string, direction: -1 | 1) => { const order = [...draft.widget_order]; const index = order.indexOf(id); const next = index + direction; if (index < 0 || next < 0 || next >= order.length) return; [order[index], order[next]] = [order[next], order[index]]; update("widget_order", order); };
  const save = async () => { try { const result = await api<{ settings: Settings }>("/api/v1/settings", { method: "PUT", body: JSON.stringify({ payload: draft }), headers: { "Content-Type": "application/json", "X-Anima-CSRF": csrf, Origin: window.location.origin } }); onSaved(result.settings); setOutcome({ status: "SUCCEEDED", operation: "settings.update", detail: "Preferences saved" }); setError(""); } catch (err) { setError(err instanceof Error ? err.message : "Settings could not be saved"); } }; const widgets = ["status", "presence", "weather", "agenda", "tasks", "controls", "conversation", "activity", "household", "reports", "health"];
  return <Card title="Household interface"><p className="muted">Presentation-only preferences are bounded by Core and never change identity, policy, or device authority.</p><div className="settings-form"><label>Appearance<select value={draft.appearance} onChange={(event) => update("appearance", event.target.value as Settings["appearance"])}><option value="system">System</option><option value="light">Light</option><option value="night">Night</option></select></label><label>Accent<select value={draft.accent} onChange={(event) => update("accent", event.target.value as Settings["accent"])}><option value="ember">Ember</option><option value="sage">Sage</option><option value="sky">Sky</option></select></label><label>Density<select value={draft.density} onChange={(event) => update("density", event.target.value as Settings["density"])}><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></label><label>Text scale<select value={draft.text_scale} onChange={(event) => update("text_scale", event.target.value as Settings["text_scale"])}><option value="small">Small</option><option value="normal">Normal</option><option value="large">Large</option></select></label><label>Layout profile<select value={draft.display_mode} onChange={(event) => update("display_mode", event.target.value as Settings["display_mode"])}><option value="wall">Wall</option><option value="tablet">Tablet</option><option value="phone">Phone</option><option value="desktop">Desktop</option></select></label><label className="checkbox"><input type="checkbox" checked={draft.reduced_motion} onChange={(event) => update("reduced_motion", event.target.checked)} /> Reduce motion</label></div><fieldset className="widget-settings"><legend>Home widgets</legend>{widgets.map((id) => { const index = draft.widget_order.indexOf(id); return <label className="widget-setting" key={id}><input type="checkbox" checked={draft.visible_widgets.includes(id)} onChange={() => toggleWidget(id)} /><span>{id}</span><button type="button" aria-label={`Move ${id} up`} disabled={index <= 0} onClick={() => moveWidget(id, -1)}>↑</button><button type="button" aria-label={`Move ${id} down`} disabled={index < 0 || index >= draft.widget_order.length - 1} onClick={() => moveWidget(id, 1)}>↓</button></label>; })}</fieldset><button onClick={() => void save()}>Save preferences</button></Card>;
}
function ScenesView({ scenes, controls, mutate }: { scenes: Scene[]; controls: Home["controls"]; mutate: (path: string, payload?: Record<string, unknown>) => Promise<MutationOutcome | null> }) {
  const [name, setName] = useState(""); const [resourceId, setResourceId] = useState(controls[0]?.control_id ?? ""); const [desiredOn, setDesiredOn] = useState(true); const [steps, setSteps] = useState<SceneStep[]>([]); const [editing, setEditing] = useState<Scene | null>(null);
  const reset = () => { setEditing(null); setName(""); setSteps([]); setResourceId(controls[0]?.control_id ?? ""); setDesiredOn(true); };
  const beginEdit = (scene: Scene) => { setEditing(scene); setName(scene.name); setSteps(scene.steps); };
  const addStep = () => { if (!resourceId || steps.some((step) => step.resource_id === resourceId)) return; setSteps([...steps, { resource_id: resourceId, desired_on: desiredOn }]); };
  const save = async (event: React.FormEvent) => { event.preventDefault(); if (!steps.length) return; const payload: Record<string, unknown> = { name, steps, enabled: editing?.enabled ?? true }; if (editing) { payload.scene_id = editing.scene_id; payload.expected_version = editing.version; } const result = await mutate("/api/v1/scenes", payload); if (result?.status === "SUCCEEDED") reset(); };
  return <div className="dashboard"><Card title={editing ? "Edit scene" : "Create a scene"}><p className="muted">Scenes are bounded presets of ANIMA canonical power states. Applying one runs each step through the normal policy, lock, fresh-state, and verification path.</p>{controls.length ? <form className="stack" onSubmit={(event) => void save(event)}><label>Scene name<input required maxLength={80} value={name} onChange={(event) => setName(event.target.value)} /></label><div className="form-grid"><label>Device<select value={resourceId} onChange={(event) => setResourceId(event.target.value)}>{controls.map((control) => <option key={control.control_id} value={control.control_id}>{control.label}</option>)}</select></label><label>State<select value={desiredOn ? "on" : "off"} onChange={(event) => setDesiredOn(event.target.value === "on")}><option value="on">On</option><option value="off">Off</option></select></label></div><button type="button" onClick={addStep} disabled={!resourceId || steps.some((step) => step.resource_id === resourceId)}>Add step</button>{steps.length ? <ol className="clean-list list-spaced">{steps.map((step, index) => <li key={step.resource_id}><span>{controls.find((control) => control.control_id === step.resource_id)?.label ?? step.resource_id}<small className="muted">{step.desired_on ? "On" : "Off"}</small></span><button type="button" onClick={() => setSteps(steps.filter((_, itemIndex) => itemIndex !== index))}>Remove</button></li>)}</ol> : <p className="muted">Add at least one commissioned power device.</p>}<div className="button-row"><button type="submit" disabled={!name.trim() || !steps.length}>{editing ? "Save scene" : "Create scene"}</button>{editing && <button type="button" onClick={reset}>Cancel</button>}</div></form> : <p className="muted">No commissioned power devices are available yet.</p>}</Card><Card title="Saved scenes"><p className="muted">ANIMA keeps scene definitions household-scoped and versioned. Each apply operation reports the governed result of every step.</p>{scenes.length ? <ul className="clean-list list-spaced">{scenes.map((scene) => <li className="integration-row" key={scene.scene_id}><span><strong>{scene.name}</strong><small className="muted">{scene.steps.length} step(s) · v{scene.version} · {scene.enabled ? "enabled" : "disabled"}</small></span><span className="button-row"><button disabled={!scene.enabled} onClick={() => void mutate(`/api/v1/scenes/${scene.scene_id}/apply`)}>Apply</button><button onClick={() => beginEdit(scene)}>Edit</button></span></li>)}</ul> : <p className="muted">No scenes configured.</p>}</Card></div>;
}
function AutomationsView({ automations, devices, controls, mutate }: { automations: Automation[]; devices: ProviderDevice[]; controls: Home["controls"]; mutate: (path: string, payload?: Record<string, unknown>) => Promise<MutationOutcome | null> }) {
  const mapped = devices.filter((item) => item.metadata.mapping_status === "MAPPED" && item.metadata.canonical_target_id);
  const [name, setName] = useState(""); const [triggerId, setTriggerId] = useState(mapped[0]?.metadata.canonical_target_id ?? ""); const [triggerState, setTriggerState] = useState<"on" | "off">("on"); const [actionId, setActionId] = useState(controls[0]?.control_id ?? ""); const [actionOn, setActionOn] = useState(true); const [enabled, setEnabled] = useState(true); const [editing, setEditing] = useState<Automation | null>(null);
  const reset = () => { setEditing(null); setName(""); setTriggerId(mapped[0]?.metadata.canonical_target_id ?? ""); setTriggerState("on"); setActionId(controls[0]?.control_id ?? ""); setActionOn(true); setEnabled(true); };
  const beginEdit = (item: Automation) => { setEditing(item); setName(item.name); setTriggerId(item.trigger_resource_id); setTriggerState(item.trigger_state); setActionId(item.action_resource_id); setActionOn(item.action_desired_on); setEnabled(item.enabled); };
  const save = async (event: React.FormEvent) => { event.preventDefault(); const payload: Record<string, unknown> = { name, trigger_resource_id: triggerId, trigger_state: triggerState, action_resource_id: actionId, action_desired_on: actionOn, enabled }; if (editing) { payload.automation_id = editing.automation_id; payload.expected_version = editing.version; } const result = await mutate("/api/v1/automations", payload); if (result?.status === "SUCCEEDED") reset(); };
  const label = (id: string) => controls.find((item) => item.control_id === id)?.label ?? mapped.find((item) => item.metadata.canonical_target_id === id)?.metadata.name ?? "Unnamed device";
  return <div className="dashboard"><Card title={editing ? "Edit automation" : "Create an automation"}><p className="muted">Automations are bounded event-to-power rules. A matching observation still passes through ANIMA policy, locking, fresh state, and verification.</p>{mapped.length && controls.length ? <form className="stack" onSubmit={(event) => void save(event)}><label>Name<input required maxLength={80} value={name} onChange={(event) => setName(event.target.value)} /></label><div className="form-grid"><label>When this device is<select value={triggerId} onChange={(event) => setTriggerId(event.target.value)}>{mapped.map((item) => <option key={item.metadata.canonical_target_id ?? item.device_handle} value={item.metadata.canonical_target_id ?? ""}>{label(item.metadata.canonical_target_id ?? "")}</option>)}</select></label><label>State<select value={triggerState} onChange={(event) => setTriggerState(event.target.value as "on" | "off")}><option value="on">On</option><option value="off">Off</option></select></label><label>Then control<select value={actionId} onChange={(event) => setActionId(event.target.value)}>{controls.map((item) => <option key={item.control_id} value={item.control_id}>{item.label}</option>)}</select></label><label>Set state<select value={actionOn ? "on" : "off"} onChange={(event) => setActionOn(event.target.value === "on")}><option value="on">On</option><option value="off">Off</option></select></label></div><label className="checkbox"><input type="checkbox" checked={enabled} onChange={(event) => setEnabled(event.target.checked)} /> Automation enabled</label><div className="button-row"><button type="submit" disabled={!name.trim() || !triggerId || !actionId}>{editing ? "Save automation" : "Create automation"}</button>{editing && <button type="button" onClick={reset}>Cancel</button>}</div></form> : <p className="muted">Commission at least one device and one power control before creating an automation.</p>}</Card><Card title="Saved automations"><p className="muted">Rules remain household-scoped and versioned. Disabled rules preserve their history without firing.</p>{automations.length ? <ul className="clean-list list-spaced">{automations.map((item) => <li className="integration-row" key={item.automation_id}><span><strong>{item.name}</strong><small className="muted">When {label(item.trigger_resource_id)} is {item.trigger_state}, set {label(item.action_resource_id)} {item.action_desired_on ? "on" : "off"} · v{item.version}</small></span><span className="button-row"><StatusPill status={item.enabled ? "ACTIVE" : "DISABLED"} /><button onClick={() => beginEdit(item)}>Edit</button></span></li>)}</ul> : <p className="muted">No automations configured.</p>}</Card></div>;
}
function Capabilities({ items }: { items: Capability[] }) { return <Card title="Capabilities"><ul className="clean-list">{items.map((item) => <li key={item.id}><span>{item.label}{item.detail && <small className="muted">{item.detail}</small>}</span><StatusPill status={item.state} /></li>)}</ul></Card>; }
function BackupsView({ backups, mutate }: { backups: BackupRecord[]; mutate: (path: string, payload?: Record<string, unknown>) => Promise<MutationOutcome | null> }) {
  const restore = async (backup: BackupRecord) => {
    const confirmed = window.confirm("Restore this ANIMA snapshot? Current household records will be replaced, and device state will require fresh Home Assistant observation.");
    if (confirmed) await mutate("/api/v1/backups/restore", { backup_id: backup.backup_id, confirm: true });
  };
  return <div className="dashboard"><Card title="ANIMA backups"><p className="muted">Create a server-owned PostgreSQL snapshot, validate an archive, or restore a validated snapshot through Core. Credentials, archive paths, and database administration stay server-side.</p><div className="button-row"><button onClick={() => void mutate("/api/v1/backups/create")}>Create backup</button></div>{backups.length ? <ul className="clean-list list-spaced">{backups.map((backup) => <li className="integration-row" key={backup.backup_id}><span><strong>{new Date(backup.captured_at).toLocaleString()}</strong><small className="muted">{backup.backup_id} · {Math.round(backup.size_bytes / 1024)} KiB · SHA-256 {backup.sha256.slice(0, 12)}…</small></span><span className="button-row"><StatusPill status={backup.restorable ? "VALID" : "INVALID"} /><button onClick={() => void mutate("/api/v1/backups/inspect", { backup_id: backup.backup_id })}>Validate</button><button disabled={!backup.restorable} onClick={() => void restore(backup)}>Restore</button></span></li>)}</ul> : <p className="muted">No server-owned snapshots are available for this household.</p>}</Card><Card title="Recovery boundary"><dl className="settings-grid"><dt>Storage</dt><dd><strong>ANIMA server</strong></dd><dt>Content</dt><dd><strong>PostgreSQL archive</strong></dd><dt>Restore</dt><dd><strong>Explicit owner confirmation</strong></dd><dt>After restore</dt><dd><strong>Physical state unknown until reobserved</strong></dd></dl><p className="muted">Restoring history never asserts that a device is currently in the restored state. Reconnect Home Assistant and refresh before acting on physical state.</p></Card></div>;
}
function zhaSetupFrom(outcome: MutationOutcome | null): ZHASetup | null {
  if (!outcome || !outcome.result || typeof outcome.result !== "object") return null;
  const value = outcome.result as { state?: unknown; setup_id?: unknown; step_id?: unknown; fields?: unknown };
  if (value.state !== "AWAITING_INPUT" || typeof value.setup_id !== "string" || typeof value.step_id !== "string" || !Array.isArray(value.fields)) return null;
  return { setup_id: value.setup_id, step_id: value.step_id, fields: value.fields as ZHASetupField[] };
}
function ManagedIntegrationsView({ items, mutate }: { items: Integration[]; mutate: (path: string, payload?: Record<string, unknown>) => Promise<MutationOutcome | null> }) {
  const [setup, setSetup] = useState<ZHASetup | null>(null);
  const [input, setInput] = useState<Record<string, string>>({});
  const ha = items.find((item) => item.plugin_id === "anima.provider.home-assistant");
  const start = async () => { const result = await mutate("/api/v1/integrations/setup-zha"); const next = zhaSetupFrom(result); if (next) { setSetup(next); setInput({}); } };
  const continueSetup = async (event: React.FormEvent) => { event.preventDefault(); if (!setup) return; const result = await mutate("/api/v1/integrations/continue-zha", { setup_id: setup.setup_id, user_input: input }); const next = zhaSetupFrom(result); if (next) { setSetup(next); setInput({}); } else if (result?.status === "SUCCEEDED" || result?.status === "FAILED") setSetup(null); };
  const fieldLabel = (name: string) => ({ device_path: "Radio device path", radio_type: "Radio type", baudrate: "Baud rate", flow_control: "Flow control" }[name] ?? name);
  return <div className="dashboard"><Card title="Registered integrations"><p className="muted">ANIMA owns the integration boundary. Credentials, hosts, and Home Assistant configuration remain server-owned.</p>{items.length ? <ul className="clean-list list-spaced">{items.map((item) => { const health = item.health; const status = health?.health ?? (item.state === "HEALTHY" ? "AVAILABLE" : item.state); return <li className="integration-row" key={item.plugin_id}><span><strong>{item.name}</strong><small className="muted">{item.description}</small><small className="muted">{item.capabilities.join(" · ")}</small>{health && <small className="muted">{health.health ?? item.state} · HA {health.connected_version ?? "version unknown"} · {health.mapped_count ?? 0} mapped / {health.unmapped_count ?? 0} awaiting commissioning{health.last_error_category ? ` · ${health.last_error_category}` : ""}</small>}</span><span className="button-row"><StatusPill status={status} />{item.plugin_id === "anima.provider.home-assistant" && item.enabled && <button onClick={() => void mutate("/api/v1/integrations/reconnect", { plugin_id: item.plugin_id })}>Reconnect</button>}{item.manageable && <button onClick={() => void mutate("/api/v1/integrations/set-enabled", { plugin_id: item.plugin_id, enabled: !item.enabled })}>{item.enabled ? "Disable" : "Enable"}</button>}</span></li>; })}</ul> : <p className="muted">No Core-registered optional integrations are available.</p>}</Card><Card title="Add a supported integration"><p className="muted">ZHA setup runs through the configured Home Assistant connection. ANIMA supports only the bounded ZHA flow here; other integration types remain explicitly unsupported.</p><div className="button-row"><button disabled={!ha?.enabled || Boolean(setup)} onClick={() => void start()}>Set up ZHA</button></div>{setup && <form className="stack setup-form" onSubmit={(event) => void continueSetup(event)}><h3>ZHA setup · {setup.step_id.replaceAll("_", " ")}</h3>{setup.fields.map((field) => <label key={field.name}>{fieldLabel(field.name)}{field.options?.length ? <select required={field.required} value={input[field.name] ?? ""} onChange={(event) => setInput({ ...input, [field.name]: event.target.value })}><option value="">Select…</option>{field.options.map((option) => <option key={option} value={option}>{option}</option>)}</select> : <input required={field.required} type={field.type === "integer" ? "number" : "text"} value={input[field.name] ?? ""} onChange={(event) => setInput({ ...input, [field.name]: event.target.value })} />}</label>)}<div className="button-row"><button type="submit">Continue setup</button><button type="button" onClick={() => setSetup(null)}>Cancel</button></div></form>}</Card><Card title="Boundary"><dl className="settings-grid"><dt>Authority</dt><dd><strong>ANIMA Core</strong></dd><dt>Configuration</dt><dd><strong>Server-owned</strong></dd><dt>Provider credentials</dt><dd><strong>Never shown here</strong></dd><dt>Supported setup</dt><dd><strong>ZHA only</strong></dd></dl><p className="muted">ANIMA never sends the browser to Home Assistant. Unsupported integration types fail explicitly rather than becoming a raw administrator backdoor.</p></Card></div>;
}
createRoot(document.getElementById("root")!).render(<StrictMode><App /></StrictMode>);
